import ActivityKit
import Foundation

/// The single `ActivityAttributes` type used by live_updates.
///
/// The widget extension generated by `dart run live_updates:create_widget`
/// contains an identical copy of this type. ActivityKit matches the two by
/// name and by their `Codable` shape, so keep them in sync when customizing.
@available(iOS 16.1, *)
public struct LiveUpdatesAttributes: ActivityAttributes {
  public struct ContentState: Codable, Hashable {
    public var title: String
    public var body: String?
    public var progress: Double?
    public var iconName: String?
    public var route: String?
    /// File name of an image in `LiveUpdatesImages.directory` (App Group).
    public var image: String?
    /// Buttons, rendered by the widget template.
    public var actions: [LiveUpdatesAction]
    public var extra: [String: String]
    /// Timer start (stopwatch) in seconds since 1970, counted by the system.
    public var timerStart: Double?
    /// Timer end (countdown) in seconds since 1970, counted by the system.
    public var timerEnd: Double?
    /// What the compact Dynamic Island shows on the trailing side
    /// (`IosLiveUpdateOptions.compactTrailing`), or `nil` for the default.
    public var compactTrailing: String?
    /// What the minimal Dynamic Island shows (`IosLiveUpdateOptions.minimal`).
    public var minimal: String?
    /// Accent color as ARGB (`IosLiveUpdateOptions.color`).
    public var tintArgb: Int?
    /// Lock Screen background as ARGB (`IosLiveUpdateOptions.backgroundColor`).
    public var backgroundArgb: Int?
    /// Lock Screen text as ARGB (`IosLiveUpdateOptions.foregroundColor`).
    public var foregroundArgb: Int?
    /// Lock Screen UI pattern (`IosLiveUpdateOptions.layout`), such as
    /// "timer", "metrics", "stepper" or "journey"; `nil` for the standard one.
    public var layout: String?
    /// `LiveUpdateContent.metrics`.
    public var metrics: [LiveUpdatesMetric]
    /// `LiveUpdateContent.steps`.
    public var steps: LiveUpdatesSteps?
    /// `LiveUpdateContent.journey`.
    public var journey: LiveUpdatesJourney?

    public init(
      title: String, body: String? = nil, progress: Double? = nil,
      iconName: String? = nil, route: String? = nil, image: String? = nil,
      actions: [LiveUpdatesAction] = [], extra: [String: String] = [:],
      timerStart: Double? = nil, timerEnd: Double? = nil,
      compactTrailing: String? = nil, minimal: String? = nil,
      tintArgb: Int? = nil, backgroundArgb: Int? = nil, foregroundArgb: Int? = nil,
      layout: String? = nil, metrics: [LiveUpdatesMetric] = [], steps: LiveUpdatesSteps? = nil,
      journey: LiveUpdatesJourney? = nil
    ) {
      self.title = title
      self.body = body
      self.progress = progress
      self.iconName = iconName
      self.route = route
      self.image = image
      self.actions = actions
      self.extra = extra
      self.timerStart = timerStart
      self.timerEnd = timerEnd
      self.compactTrailing = compactTrailing
      self.minimal = minimal
      self.tintArgb = tintArgb
      self.backgroundArgb = backgroundArgb
      self.foregroundArgb = foregroundArgb
      self.layout = layout
      self.metrics = metrics
      self.steps = steps
      self.journey = journey
    }

    // Lenient decoding so APNs `content-state` may omit optional keys.
    public init(from decoder: Decoder) throws {
      let c = try decoder.container(keyedBy: CodingKeys.self)
      title = try c.decode(String.self, forKey: .title)
      body = try c.decodeIfPresent(String.self, forKey: .body)
      progress = try c.decodeIfPresent(Double.self, forKey: .progress)
      iconName = try c.decodeIfPresent(String.self, forKey: .iconName)
      route = try c.decodeIfPresent(String.self, forKey: .route)
      image = try c.decodeIfPresent(String.self, forKey: .image)
      actions = try c.decodeIfPresent([LiveUpdatesAction].self, forKey: .actions) ?? []
      extra = try c.decodeIfPresent([String: String].self, forKey: .extra) ?? [:]
      timerStart = try c.decodeIfPresent(Double.self, forKey: .timerStart)
      timerEnd = try c.decodeIfPresent(Double.self, forKey: .timerEnd)
      compactTrailing = try c.decodeIfPresent(String.self, forKey: .compactTrailing)
      minimal = try c.decodeIfPresent(String.self, forKey: .minimal)
      tintArgb = try c.decodeIfPresent(Int.self, forKey: .tintArgb)
      backgroundArgb = try c.decodeIfPresent(Int.self, forKey: .backgroundArgb)
      foregroundArgb = try c.decodeIfPresent(Int.self, forKey: .foregroundArgb)
      layout = try c.decodeIfPresent(String.self, forKey: .layout)
      // Layout data that does not decode is left out (one bad metric is
      // skipped) instead of rejecting the whole content state.
      metrics =
        ((try? c.decodeIfPresent([LiveUpdatesLossy<LiveUpdatesMetric>].self, forKey: .metrics))
          ?? nil)?.compactMap(\.value) ?? []
      steps = (try? c.decodeIfPresent(LiveUpdatesSteps.self, forKey: .steps)) ?? nil
      journey = (try? c.decodeIfPresent(LiveUpdatesJourney.self, forKey: .journey)) ?? nil
    }
  }

  /// Key chosen by the app (`LiveUpdates.startOrUpdate`) or by the server in
  /// push-to-start `attributes`, used to find the activity again.
  public var key: String?

  public init(key: String? = nil) {
    self.key = key
  }
}

/// A value of `LiveUpdateContent.metrics`. `type` is "integer", "decimal",
/// "text", "timer", "stopwatch" (with `number` in milliseconds since 1970),
/// "pausedTimer" or "pausedStopwatch" (with `number` as a duration in
/// milliseconds).
public struct LiveUpdatesMetric: Codable, Hashable {
  public var label: String
  public var type: String
  public var number: Double?
  public var text: String?
  public var unit: String?
  public var fractionDigits: Int?
  public var semanticStyle: String?

  enum CodingKeys: String, CodingKey {
    case label, type, value, unit, fractionDigits, semanticStyle
  }

  public init(
    label: String, type: String, number: Double? = nil, text: String? = nil,
    unit: String? = nil, fractionDigits: Int? = nil, semanticStyle: String? = nil
  ) {
    self.label = label
    self.type = type
    self.number = number
    self.text = text
    self.unit = unit
    self.fractionDigits = fractionDigits
    self.semanticStyle = semanticStyle
  }

  public init(from decoder: Decoder) throws {
    let c = try decoder.container(keyedBy: CodingKeys.self)
    label = try c.decodeIfPresent(String.self, forKey: .label) ?? ""
    type = try c.decode(String.self, forKey: .type)
    number = try? c.decodeIfPresent(Double.self, forKey: .value)
    text = number == nil ? try? c.decodeIfPresent(String.self, forKey: .value) : nil
    unit = try c.decodeIfPresent(String.self, forKey: .unit)
    fractionDigits = try c.decodeIfPresent(Int.self, forKey: .fractionDigits)
    semanticStyle = try c.decodeIfPresent(String.self, forKey: .semanticStyle)
  }

  public func encode(to encoder: Encoder) throws {
    var c = encoder.container(keyedBy: CodingKeys.self)
    try c.encode(label, forKey: .label)
    try c.encode(type, forKey: .type)
    if let number { try c.encode(number, forKey: .value) } else { try c.encodeIfPresent(text, forKey: .value) }
    try c.encodeIfPresent(unit, forKey: .unit)
    try c.encodeIfPresent(fractionDigits, forKey: .fractionDigits)
    try c.encodeIfPresent(semanticStyle, forKey: .semanticStyle)
  }
}

/// `LiveUpdateContent.steps`: stage names and the index of the current one.
public struct LiveUpdatesSteps: Codable, Hashable {
  public var labels: [String]
  public var current: Int

  enum CodingKeys: String, CodingKey { case labels, current }

  public init(labels: [String], current: Int) {
    self.labels = labels
    self.current = current
  }

  public init(from decoder: Decoder) throws {
    let c = try decoder.container(keyedBy: CodingKeys.self)
    labels = (try? c.decodeIfPresent([String].self, forKey: .labels)) ?? []
    current = (try? c.decodeIfPresent(Int.self, forKey: .current)) ?? 0
  }
}

/// Decodes a `T`, or `nil` when the value does not decode.
struct LiveUpdatesLossy<T: Decodable>: Decodable {
  let value: T?

  init(from decoder: Decoder) throws {
    value = try? T(from: decoder)
  }
}

/// `LiveUpdateContent.journey`.
public struct LiveUpdatesJourney: Codable, Hashable {
  public var from: String
  public var to: String
  public var fromDetail: String?
  public var toDetail: String?

  public init(from: String, to: String, fromDetail: String? = nil, toDetail: String? = nil) {
    self.from = from
    self.to = to
    self.fromDetail = fromDetail
    self.toDetail = toDetail
  }
}

/// A button on a Live Activity (`LiveUpdateAction` in Dart).
public struct LiveUpdatesAction: Codable, Hashable, Identifiable {
  public var id: String
  public var title: String
  /// SF Symbol name.
  public var systemImage: String?
  /// Opens the app instead of running in the background.
  public var opensApp: Bool
  /// Requires the device to be unlocked before the press is handled.
  public var requiresUnlock: Bool

  public init(
    id: String, title: String, systemImage: String? = nil, opensApp: Bool = false,
    requiresUnlock: Bool = false
  ) {
    self.id = id
    self.title = title
    self.systemImage = systemImage
    self.opensApp = opensApp
    self.requiresUnlock = requiresUnlock
  }

  public init(from decoder: Decoder) throws {
    let c = try decoder.container(keyedBy: CodingKeys.self)
    id = try c.decode(String.self, forKey: .id)
    title = try c.decode(String.self, forKey: .title)
    systemImage = try c.decodeIfPresent(String.self, forKey: .systemImage)
    opensApp = try c.decodeIfPresent(Bool.self, forKey: .opensApp) ?? false
    requiresUnlock = try c.decodeIfPresent(Bool.self, forKey: .requiresUnlock) ?? false
  }
}

/// Images shared between the app and the widget extension through the App
/// Group named by the `LiveUpdatesAppGroup` Info.plist key of each target.
public enum LiveUpdatesImages {
  /// The shared directory, or `nil` when no App Group is configured.
  public static var directory: URL? {
    guard let group = Bundle.main.object(forInfoDictionaryKey: "LiveUpdatesAppGroup") as? String,
      let container = FileManager.default.containerURL(
        forSecurityApplicationGroupIdentifier: group)
    else { return nil }
    return container.appendingPathComponent("live_updates", isDirectory: true)
  }

  /// URL of the image `name` written by the app.
  public static func url(_ name: String?) -> URL? {
    guard let name, !name.contains("/") else { return nil }
    return directory?.appendingPathComponent(name)
  }
}
